fn parse_num(s: &str) -> Result<i32, String> {
    let n: i32 = s.trim().parse().map_err(|_| format!("not a number: {}", s))?;
    Ok(n * 2)
}
fn main() {
    println!("{:?}", parse_num(" 21 "));
    println!("{:?}", parse_num("x"));
}

