use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};

struct Ready(i32);

impl Future for Ready {
    type Output = i32;
    fn poll(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<i32> {
        Poll::Ready(self.get_mut().0)
    }
}

fn make_ready(v: i32) -> Ready {
    Ready(v)
}

